# R script to visualize LOESS smoothing results
# Generated by Fortran test program

# Load libraries
library(ggplot2)
library(dplyr)
library(tidyr)

# Read data
raw_data <- read.table("raw_data.tsv", header=TRUE, sep="\t")
loess_01 <- read.table("loess_span_0.1.tsv", header=TRUE, sep="\t")
loess_03 <- read.table("loess_span_0.3.tsv", header=TRUE, sep="\t")
loess_05 <- read.table("loess_span_0.5.tsv", header=TRUE, sep="\t")
loess_08 <- read.table("loess_span_0.8.tsv", header=TRUE, sep="\t")

# Combine all LOESS results
all_loess <- loess_01 %>%
  left_join(loess_03, by="x") %>%
  left_join(loess_05, by="x") %>%
  left_join(loess_08, by="x") %>%
  pivot_longer(cols = -x, names_to = "method", values_to = "y")

# Plot 1: Multi-scale signal with different spans
p1 <- ggplot() +
  geom_point(data = raw_data, aes(x = x_raw, y = y_raw),
             alpha = 0.5, size = 1.5, color = "gray60") +
  geom_line(data = all_loess, aes(x = x, y = y, color = method),
            linewidth = 1.2) +
  scale_color_manual(
    name = "LOESS span",
    values = c("y_span_0.1" = "#E41A1C",
               "y_span_0.3" = "#377EB8",
               "y_span_0.5" = "#4DAF4A",
               "y_span_0.8" = "#984EA3"),
    labels = c("0.1", "0.3", "0.5", "0.8")) +
  labs(title = "LOESS Smoothing with Different Spans",
       subtitle = "Small span = local fitting, Large span = global smoothing",
       x = "X", y = "Y") +
  theme_minimal() +
  theme(legend.position = "bottom")

# Plot 2: Discontinuity handling
disc_raw <- read.table("discontinuity_raw.tsv", header=TRUE, sep="\t")
disc_loess <- read.table("discontinuity_loess.tsv", header=TRUE, sep="\t")

p2 <- ggplot() +
  geom_point(data = disc_raw, aes(x = x_disc, y = y_disc),
             alpha = 0.5, size = 1.5, color = "gray60") +
  geom_line(data = disc_loess, aes(x = x_disc, y = y_disc_smoothed),
            color = "#D95F02", linewidth = 1.5) +
  geom_vline(xintercept = 5.0, linetype = "dashed", color = "red", alpha = 0.5) +
  labs(title = "LOESS Handling of Discontinuity (span=0.3)",
       subtitle = "Vertical line shows actual discontinuity location",
       x = "X", y = "Y") +
  theme_minimal()

# Plot 3: Varying noise
var_raw <- read.table("varying_noise_raw.tsv", header=TRUE, sep="\t")
var_02 <- read.table("varying_noise_span_0.2.tsv", header=TRUE, sep="\t")
var_04 <- read.table("varying_noise_span_0.4.tsv", header=TRUE, sep="\t")

p3 <- ggplot() +
  geom_point(data = var_raw, aes(x = x_var, y = y_var),
             alpha = 0.5, size = 1.5, color = "gray60") +
  geom_line(data = var_02, aes(x = x_var, y = y_var_span_0.2),
            color = "#1B9E77", linewidth = 1.2) +
  geom_line(data = var_04, aes(x = x_var, y = y_var_span_0.4),
            color = "#7570B3", linewidth = 1.2) +
  labs(title = "LOESS with Heteroscedastic Noise",
       subtitle = "Noise amplitude increases with X",
       x = "X", y = "Y") +
  theme_minimal()

# Save plots
pdf("loess_visualization.pdf", width = 10, height = 12)
print(p1)
print(p2)
print(p3)
dev.off()

# Also save individual PNGs
ggsave("loess_spans_comparison.png", p1, width = 8, height = 6, dpi = 300)
ggsave("loess_discontinuity.png", p2, width = 8, height = 6, dpi = 300)
ggsave("loess_varying_noise.png", p3, width = 8, height = 6, dpi = 300)

cat("Plots saved as:")
cat("\n• loess_visualization.pdf (all plots)")
cat("\n• loess_spans_comparison.png")
cat("\n• loess_discontinuity.png")
cat("\n• loess_varying_noise.png")
cat("\n\nData files available for inspection.")
